+
+  private async *executeSerial(
+    preflighted: readonly PreflightedToolCall[],
+    allCalls: readonly ToolCall[],
+    options: ToolExecutorExecuteOptions,
+  ): AsyncIterable<ToolExecutionResult> {
+    let stopBatch = false;
+    for (const [index, call] of preflighted.entries()) {
+      let prepared: {
+        task: ToolExecutionTask;
+        resolvedAccesses?: ToolAccesses;
+        stopBatchAfterThis?: boolean;
+      };
+      if (stopBatch) {
+        prepared = this.prepareSkippedToolCall(call, options);
+      } else if (options.signal.aborted && call.kind === 'runnable') {
+        this.dispatchToolCall(call, call.args, options);
+        prepared = {
+          task: makeResolvedTask(
+            makeErrorToolResult(call, call.args, abortedToolOutput(call.toolName, options.signal.reason)),
+            'aborted',
+          ),
+        };
+      } else {
+        prepared = await this.prepareToolCall(call, allCalls, options);
+      }
+      if (prepared.stopBatchAfterThis === true) stopBatch = true;
+
+      const startedAt = Date.now();
+      const executed = await prepared.task.execute(options.signal);
+      const timedResult: TimedToolResult = {
+        index,
+        result: executed.result,
+        outcome: executed.outcome,
+        durationMs: Math.max(0, Date.now() - startedAt),
+      };
+      // Finalize and publish this result before preparing the next tool.
+      yield await this.finalizeTimedResult({ ...prepared, call }, timedResult, options);
     }
   }
